<dialog class="epf-modal" data-finance-modal="expense-create"><form method="POST" action="{{ route('projects-unified.finance.expense.store', $site) }}">@csrf<header><div><small>CHI PHÍ KHÁC</small><h3>Thêm chi phí</h3></div><button type="button" data-finance-close><i class="bi bi-x-lg"></i></button></header><div class="epf-modal-body epf-modal-grid"><label>Ngày phát sinh<input type="date" name="expense_date" value="{{ now()->format('Y-m-d') }}" required></label><label>Nhóm chi phí<select name="category"><option value="supplier">Nhà cung cấp</option><option value="service">Dịch vụ</option><option value="travel">Đi lại</option><option value="rental">Thuê ngoài</option><option value="other">Khác</option></select></label><label>Số tiền<input type="number" name="amount" min="1" step="1" required></label><label>Người nhận / NCC<input name="payee"></label><label class="full">Nội dung<input name="description" required></label><label class="full">Ghi chú<textarea name="note" rows="2"></textarea></label></div><footer><button type="button" class="pword-btn light" data-finance-close>Hủy</button><button class="pword-btn primary">Thêm chi phí</button></footer></form></dialog>

<dialog class="epf-modal" data-finance-modal="expense-edit"><form method="POST" data-expense-edit-form data-action-template="{{ route('projects-unified.finance.expense.update', ['site'=>$site->id,'expense'=>0]) }}">@csrf @method('PUT')<header><div><small>LƯU VẾT THAY ĐỔI</small><h3>Sửa chi phí</h3></div><button type="button" data-finance-close><i class="bi bi-x-lg"></i></button></header><div class="epf-modal-body epf-modal-grid"><label>Ngày phát sinh<input type="date" name="expense_date" required></label><label>Nhóm chi phí<select name="category"><option value="supplier">Nhà cung cấp</option><option value="service">Dịch vụ</option><option value="travel">Đi lại</option><option value="rental">Thuê ngoài</option><option value="other">Khác</option></select></label><label>Số tiền<input type="number" name="amount" min="1" required></label><label>Người nhận / NCC<input name="payee"></label><label class="full">Nội dung<input name="description" required></label><label class="full">Ghi chú<textarea name="note" rows="2"></textarea></label><label class="full">Lý do chỉnh sửa<input name="change_reason" required placeholder="Bắt buộc nhập để lưu lịch sử"></label></div><footer><button type="button" class="pword-btn light" data-finance-close>Hủy</button><button class="pword-btn primary">Lưu thay đổi</button></footer></form></dialog>

<script>
document.addEventListener('DOMContentLoaded',()=>{const root=document.querySelector('[data-finance-root]');if(!root)return;const modal=n=>root.querySelector(`[data-finance-modal="${n}"]`);root.addEventListener('click',e=>{const open=e.target.closest('[data-finance-open]');if(open){modal(open.dataset.financeOpen)?.showModal();return}const close=e.target.closest('[data-finance-close]');if(close){close.closest('dialog')?.close();return}const pay=e.target.closest('[data-finance-edit-payment]');if(pay){const d=modal('payment-edit'),f=d.querySelector('form');f.action=f.dataset.actionTemplate.replace('/record/0',`/${pay.dataset.source}/${pay.dataset.id}`);for(const[n,v]of Object.entries({amount:pay.dataset.amount,paid_at:pay.dataset.date,payment_method:pay.dataset.method,account_id:pay.dataset.account,transaction_reference:pay.dataset.reference,payer_name:pay.dataset.payer,note:pay.dataset.note}))if(f.elements[n])f.elements[n].value=v||'';d.showModal();return}const exp=e.target.closest('[data-finance-edit-expense]');if(exp){const d=modal('expense-edit'),f=d.querySelector('form');f.action=f.dataset.actionTemplate.replace('/0',`/${exp.dataset.id}`);for(const[n,v]of Object.entries({expense_date:exp.dataset.date,category:exp.dataset.category,amount:exp.dataset.amount,payee:exp.dataset.payee,description:exp.dataset.description,note:exp.dataset.note}))if(f.elements[n])f.elements[n].value=v||'';d.showModal()}});root.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d)d.close()}))});
</script>
